html:
{% set mr_approved_by = doc.ts_mr_approved_by or "" %}
{% set approver_name = frappe.db.get_value("User", mr_approved_by, "full_name") if mr_approved_by else "" %}
{% set is_ceo = frappe.db.get_value("Has Role", {"parent": mr_approved_by, "role": "CEO"}, "name") if mr_approved_by else "" %}
{% set is_md = frappe.db.get_value("Has Role", {"parent": mr_approved_by, "role": "MD"}, "name") if mr_approved_by else "" %}
{% set is_approved = doc.ts_mr_status == "Approved" %}
{% set has_terms = doc.tc_name or doc.terms or doc.ts_remark %}

<style>
@page { size: A4; margin: 8mm 10mm 8mm 10mm; }
body { font-family: Arial, sans-serif; font-size: 11px; color: #333; }
.mr-header-img { width: 100%; max-height: 80px; }
.mr-title { text-align: center; margin: 8px 0 2px; font-size: 16px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.mr-subtitle { text-align: center; font-size: 9px; font-style: italic; color: #555; margin: 2px 0; }
.mr-addr { text-align: center; font-size: 8px; color: #666; margin: 1px 0; }
.mr-info-table { width: 100%; border-collapse: collapse; margin: 6px 0; }
.mr-info-table td { padding: 3px 6px; font-size: 10px; vertical-align: top; border: 1px solid #ddd; }
.mr-info-label { font-weight: bold; width: 115px; }
.mr-items { width: 100%; border-collapse: collapse; margin: 6px 0; }
.mr-items th { border: 1px solid #333; padding: 4px 6px; font-size: 9px; text-transform: uppercase; text-align: center; font-weight: bold; }
.mr-items td { border: 1px solid #ccc; padding: 3px 6px; font-size: 10px; }
.mr-items .num { text-align: right; }
.mr-items .ctr { text-align: center; }
.mr-terms-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 10px 0 4px; }
.mr-terms-body { font-size: 10px; line-height: 1.6; }
.mr-stamp-area { text-align: right; margin-top: 30px; padding-right: 20px; }
.mr-stamp-img { width: 100px; height: auto; opacity: 0.85; }
.mr-stamp-label { font-size: 10px; font-weight: bold; text-align: right; margin-top: 4px; padding-right: 25px; }
.mr-footer { margin-top: 20px; border-top: 1px solid #ccc; padding-top: 8px; text-align: center; font-size: 8px; color: #555; }
.mr-footer b { font-size: 9px; color: #333; }
.mr-sig-line { border-top: 1px solid #333; width: 150px; margin: 40px 0 2px auto; }
.mr-sig-label { text-align: right; font-size: 10px; font-weight: bold; }
.mr-wrap { position: relative; }
.mr-draft-watermark { position: absolute; top: 35%; left: 10%; font-size: 100px; color: rgba(255,0,0,0.08); font-weight: bold; -webkit-transform: rotate(-35deg); transform: rotate(-35deg); z-index: 0; letter-spacing: 20px; pointer-events: none; }
.mr-status-badge { display: inline-block; padding: 2px 10px; border-radius: 3px; font-size: 10px; font-weight: bold; }
.mr-status-approved { background: #d4edda; color: #155724; }
.mr-status-pending { background: #fff3cd; color: #856404; }
.mr-status-draft { background: #f8d7da; color: #721c24; }
.page-break { page-break-before: always; }
</style>

<div class="mr-wrap">

<!-- HEADER IMAGE -->
<img src="/files/Header.png" class="mr-header-img" onerror="this.style.display='none'">

<!-- TITLE -->
{% if not is_approved %}
<div style="text-align:center; font-size:14px; font-weight:bold; color:#cc0000; letter-spacing:2px; margin:6px 0 0;">DRAFT</div>
{% endif %}
<div class="mr-title">MATERIAL REQUEST</div>
<div class="mr-subtitle">Internal requisition for materials, services, or assets</div>
<div class="mr-addr">Betul Biofuel Private Limited | Bodi Junawani, Betul (M.P)</div>

<!-- MR INFO -->
<table class="mr-info-table">
<tr>
  <td class="mr-info-label">Request No.</td>
  <td><b>{{ doc.name }}</b></td>
  <td class="mr-info-label">Date</td>
  <td>{{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }}</td>
</tr>
<tr>
  <td class="mr-info-label">Purpose</td>
  <td><b>{{ doc.material_request_type }}</b></td>
  <td class="mr-info-label">Required By</td>
  <td>{{ frappe.format(doc.schedule_date, {"fieldtype": "Date"}) if doc.schedule_date else "" }}</td>
</tr>
<tr>
  <td class="mr-info-label">Company</td>
  <td>{{ doc.company }}</td>
  <td class="mr-info-label">Cost Center</td>
  <td><b>{{ doc.cost_center or "" }}</b></td>
</tr>
<tr>
  <td class="mr-info-label">Requested By</td>
  <td>{{ doc.ts_username or "" }}{% if doc.ts_department_name %} ({{ doc.ts_department_name }}){% endif %}</td>
  <td class="mr-info-label">Priority</td>
  <td>{{ doc.ts_priority or "" }}</td>
</tr>
<tr>
  <td class="mr-info-label">Project</td>
  <td>{{ doc.ts_project or doc.project or "" }}</td>
  <td class="mr-info-label">Approval Status</td>
  <td>
    {% if is_approved %}<span class="mr-status-badge mr-status-approved">Approved</span>
    {% elif doc.ts_mr_status %}<span class="mr-status-badge mr-status-pending">{{ doc.ts_mr_status }}</span>
    {% else %}<span class="mr-status-badge mr-status-draft">Draft</span>{% endif %}
  </td>
</tr>
</table>

<!-- ITEMS TABLE -->
<table class="mr-items">
<thead>
<tr>
  <th style="width:30px">S.No</th>
  <th>Item Code</th>
  <th>Item Name</th>
  <th style="width:70px">Quantity</th>
  <th style="width:50px">UOM</th>
  <th>Warehouse</th>
  <th>Location</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td>{{ item.item_code }}</td>
  <td>{{ item.item_name or "" }}{% if item.description and item.description != item.item_name %}<br><span style="font-size:8px;color:#888;">{{ item.description[:60] }}</span>{% endif %}</td>
  <td class="num">{{ frappe.format(item.qty, {"fieldtype": "Float", "precision": 2}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom }}</td>
  <td style="font-size:9px;">{{ item.warehouse or "" }}</td>
  <td style="font-size:9px;">{{ item.ts_delivery_location or "" }}</td>
</tr>
{% endfor %}
</tbody>
</table>

<!-- TERMS & REMARKS -->
{% if has_terms %}
<div class="page-break"></div>

{% if doc.tc_name or doc.terms %}
<div class="mr-terms-heading">Terms and Conditions</div>
<div class="mr-terms-body">{{ doc.terms or "" }}</div>
{% endif %}

{% if doc.ts_remark %}
<div class="mr-terms-heading">Remarks</div>
<div class="mr-terms-body">{{ doc.ts_remark }}</div>
{% endif %}
{% endif %}

<!-- SIGNATURE -->
<div class="mr-stamp-area">
  <div class="mr-sig-line"></div>
  <div class="mr-sig-label">Authority Signature</div>
</div>

<!-- FOOTER -->
<div class="mr-footer">
<b>AUTH. SIGNATORY</b><br>
<b>KINDLY DESPATCH YOUR ORIGINAL DOCUMENTS TO OUR OFFICE</b><br>
2nd Floor, LIC Building, Gurudwara Road, Betul, Ganj, Betul – 460001<br>
MOBILE NO. 7999844563 | E-mail: purchasemanager@betulbiofuel.com
</div>

</div><!-- /mr-wrap -->
